"""Compile every number the paper may quote into results/paper_numbers.md, straight from the result files (no hand-typed values).
Each section names its source file(s). Run: uv run --with tabulate python -I scripts/73_build_paper_numbers.py
FIGDATA=read: the blocks that need per-participant files take their aggregate values from results/paper_numbers_agg.json (written by a normal run).
"""
import glob, json, os, numpy as np, pandas as pd
from scipy.stats import ttest_rel, spearmanr, mannwhitneyu
R = "results"; out = []
def H(t): out.append(f"\n## {t}\n")
def md(df, digits=3, note=None):
    out.append(df.round(digits).to_markdown(index=False)); out.append("")
    if note: out.append(f"_{note}_\n")
def rd(f): return pd.read_csv(os.path.join(R, f))
# Blocks computed from per-participant files (sign check, basis dependence, free-text decoding, reliability, EVA interpretation, synthetic raters, London z)
# store their aggregate values in results/paper_numbers_agg.json; with FIGDATA=read these values are read back, so this script runs on the aggregate
# files alone (public release). The formatting code below is the same in both modes.
AGG_READ = os.environ.get("FIGDATA") == "read"; AGG_PATH = os.path.join(R, "paper_numbers_agg.json"); AGG = json.load(open(AGG_PATH)) if AGG_READ else {}
def agg(key, compute):
    if not AGG_READ: AGG[key] = json.loads(json.dumps(compute(), default=lambda o: o.item()))      # numpy scalars -> exact Python numbers; same values as after a reload
    return AGG[key]
out.append("# Paper numbers (machine-generated by scripts/73_build_paper_numbers.py)\n\nAll tables are read from results/*.csv; see the source named at each section. ρ = Spearman, r = Pearson, acc = odd-one-out accuracy. 'pop' = population baseline from training folds only.\n")
# ---------------- Xu et al. arrangement experiments
for e in (1, 2):
    H(f"Xu et al. 2026 Experiment {e}: 10-fold CV, fold-out participants (results/summary_exp{e}_cv.csv)")
    s = rd(f"summary_exp{e}_cv.csv"); md(s[["method", "n", "rho_hold", "rho_tr_all", "rho_tr_unseen", "ceiling_splithalf", "hold_over_ceiling"]], note="rho_hold: held-out arrangement trials; rho_tr_unseen: retest task (Exp 1: 40 faces, on average 8 overlap with the participant's own 20 = mostly unseen faces; Exp 2: retest within the participant's 20 faces); ceiling_splithalf: split-half reliability of the estimation trials; hold_over_ceiling = rho_hold / ceiling")
    p = rd(f"paired_exp{e}_cv.csv"); md(p, 4, note="paired per-participant differences (mean, s.e.m., paired t p, Wilcoxon p)")
    lc = rd(f"learning_curve_exp{e}_cv.csv"); md(lc[lc.M == 4].pivot(index="n_est_fixed", columns="kind", values="mean").reset_index(), note=f"results/learning_curve_exp{e}_cv.csv: held-out ρ (fixed hold-out set) vs number of estimation trials, M=4")
    st = rd(f"reliability_strata_exp{e}_cv.csv"); md(st[st.method.isin(["D0-M4", "D1-M4", "D2-M4"])].pivot(index="stratum", columns="method", values="rho_hold").reset_index(), note=f"results/reliability_strata_exp{e}_cv.csv: held-out ρ by quartile of the participant's split-half reliability")
    z = glob.glob(os.path.join(R, f"z_icc_exp{e}_D*_M4_cv.csv"))
    if z:
        zz = pd.read_csv(z[0]); out.append(f"z stability ({os.path.basename(z[0])}): ICC(estimation vs hold-out trials) mean over dims and folds = {zz.icc_est_hold.mean():.3f}; ICC(estimation vs retest task) = {zz.icc_est_tr.mean():.3f}; per-dim ICC est-hold = {zz.groupby('dim').icc_est_hold.mean().round(3).to_dict()}\n")
    for f in glob.glob(os.path.join(R, f"h5_attributes_exp{e}_D*_M4_cv.csv")):
        a = pd.read_csv(f); a = a[a.features == "z"].groupby("target")[["acc", "null_mean", "null_sd", "p", "n"]].mean().reset_index(); out.append(f"H5 ({os.path.basename(f)}): decoding perceiver attributes from z (balanced accuracy, permutation null; averaged over fold models)\n"); md(a)
    def h6():
        o = []
        for f in glob.glob(os.path.join(R, f"h6_text_exp{e}_D*_M4_cv.csv")):
            t = pd.read_csv(f); d1 = t.z_text - t["pop"]; d2 = t.z_arr - t["pop"]; o.append(dict(file=os.path.basename(f), d1=d1.mean(), se=d1.std() / np.sqrt(len(d1)), p=ttest_rel(t.z_text, t["pop"]).pvalue, n=len(t), d2=d2.mean(), pop=t["pop"].mean(), z_text=t.z_text.mean(), z_arr=t.z_arr.mean()))
        return o
    for h in agg(f"h6_text_exp{e}", h6): out.append(f"H6 ({h['file']}): held-out ρ with z decoded from free text vs pop: {h['d1']:+.4f} (s.e.m. {h['se']:.4f}, paired t p = {h['p']:.2g}, n = {h['n']}); z from arrangements vs pop: {h['d2']:+.4f}; means pop {h['pop']:.3f}, z_text {h['z_text']:.3f}, z_arr {h['z_arr']:.3f}\n")
    def rel():
        rr = rd(f"repro_exp{e}_reliability.csv"); return dict(sh=rr.split_half_rho.mean(), sb=rr.split_half_rho_sb.mean(), tr=rr.tr_rho.mean(), n=len(rr))
    q = agg(f"reliability_exp{e}", rel); out.append(f"Participant reliability (results/repro_exp{e}_reliability.csv): mean split-half ρ = {q['sh']:.3f} (Spearman-Brown {q['sb']:.3f}), mean retest ρ = {q['tr']:.3f}, n = {q['n']}\n")
# ---------------- generalization datasets
H("Generalization datasets: summary tables (results/<src>_summary.csv) and paired contrasts (results/<src>_paired.csv)")
SRCS = [("london", "London Set, ratings version (learned face embedding), 102 faces x 2,501 raters"), ("london_img", "London Set, CLIP image version (seen = rater's remaining training faces; unseen = faces held out from training)"), ("london_hyb", "London Set, hybrid (learned + CLIP)"),
        ("avfs", "AVFS novel set, 56 faces, triplets"), ("avfs_img", "AVFS main set, 4,921 FFHQ faces, CLIP image version (acc_main = held-out triplets; acc_novel = 56 unseen faces; acc_same = 1,000 common triplets; agree_modal_loo = leave-one-out modal-vote agreement)"),
        ("facesim2D", "FaceSim3D 2D, CFD 100 faces, triplets"), ("facesim3D", "FaceSim3D 3D"), ("lapis_img", "LAPIS artworks, CLIP image version"), ("aadb_img", "AADB photographs, CLIP image version (68 raters >= 100 ratings)"), ("eva_img", "EVA photographs, CLIP image version (175 raters >= 100 ratings)"), ("eva_img_n68", "EVA, random 68 raters per seed (power analysis)"),
        ("jester", "Jester jokes, D=8 (learned joke embedding + sentence embedding)"), ("jester_D16", "Jester, D=16 M=8"), ("jester_D32", "Jester, D=32 M=8"), ("scut", "SCUT-FBP5500 faces, 60 raters x 5,500 faces, CLIP + learned"), ("scut_asian2cauc", "SCUT: train on Asian faces, unseen = Caucasian faces"), ("scut_cauc2asian", "SCUT: train on Caucasian faces, unseen = Asian faces"),
        ("keller", "Keller & Vosshall odor pleasantness, high concentration (original item penalty)"), ("keller_fix", "Keller & Vosshall, high concentration, corrected per-item penalty (D0/D1 only)"), ("keller_both", "Keller & Vosshall, both concentrations")]
KEEP = {"D1 - D0", "D2 - D1", "D3 - D2", "D2 - D0", "D0 - pop(raters)", "D0 - pop(image ridge)", "D1 - pop(image ridge)", "D1 - pop", "D0 - pop", "D1 amort - direct", "D2 amort - direct"}
for src, desc in SRCS:
    if not os.path.exists(os.path.join(R, f"{src}_summary.csv")): continue
    out.append(f"### {src}: {desc}\n"); md(rd(f"{src}_summary.csv"))
    p = rd(f"{src}_paired.csv"); md(p[p.contrast.isin(KEEP)], 4)
# ---------------- simulated-participant controls
H("Simulated-participant controls (results/sim_recovery_summary.csv = noise 0.45, Exp-1-like reliability; results/sim_recovery_n03_summary.csv = noise 0.30, Exp-2-like)")
for f in ("sim_recovery_summary.csv", "sim_recovery_n03_summary.csv"):
    s = rd(f); g = s.groupby(["exp", "sim", "kind"])[["sim_splithalf", "hold_pop", "hold_amortized", "hold_direct", "hold_oracle", "true_pop", "true_amortized"]].mean().reset_index(); out.append(f"{f} (sim = generating type of individual differences, kind = fitted model; hold_* = held-out ρ, true_* = ρ with the participant's true full RDM; means over seeds)\n"); md(g)
# ---------------- sensitivity
H("Sensitivity of the generalization results to seeds, D and M (results/generalization_sens.csv)")
md(rd("generalization_sens.csv"), 4)
# ---------------- sign check
H("Sign check (results/sign_check_<ds>_raters.csv, _gain.csv): do raters read shared axes in the opposite direction?")
def _rows():
    rows = []
    for ds, nest in (("london", 40), ("scut", 500), ("eva", 100), ("lapis", 100), ("jester", 50)):
        r = rd(f"sign_check_{ds}_raters.csv"); A = rd(f"sign_check_{ds}_gain.csv"); rr = r.groupby("rater").mean(numeric_only=True)
        q = pd.qcut(A.U_free.rank(method="first"), 4, labels=False); qm = A.groupby(q).d2_minus_d1.mean()
        rows.append(dict(dataset=ds, n_raters=r.rater.nunique(), median_ratings=r.n_rat.median(), weight_splithalf_r=rr.halves_r.mean(), frac_cos_neg=(rr.cos_pop < 0).mean(), U_flipped_energy=rr.U_free.mean(), U_noise_unbiased=rr.U_unb.mean(),
                         gap_free_minus_D1=rr.gap_free_d1.mean(), gap_se=rr.gap_free_d1.std() / np.sqrt(len(rr)), frac_gap_gt_0_02=(rr.gap_free_d1 > 0.02).mean(), n_est_for_D2_D1=nest, mean_D2_D1=A.d2_minus_d1.mean(),
                         spearman_U_vs_D2D1=spearmanr(A.U_free, A.d2_minus_d1, nan_policy="omit")[0], spearman_p=spearmanr(A.U_free, A.d2_minus_d1, nan_policy="omit")[1], spearman_cos_vs_D2D1=spearmanr(A.cos_pop, A.d2_minus_d1, nan_policy="omit")[0],
                         D2D1_Q1=qm.get(0, np.nan), D2D1_Q2=qm.get(1, np.nan), D2D1_Q3=qm.get(2, np.nan), D2D1_Q4=qm.get(3, np.nan)))
    return rows
rows = agg("sign_check", _rows)
md(pd.DataFrame(rows), 3, note="Per-rater weights = ridge of the rater's z-scored ratings on the fold model's embedding (standardised dims); U = fraction of weight energy on dims whose sign is opposite to the population weight; U_noise_unbiased uses the split-half product; gap = split-half CV r of a free linear readout minus a D1-constrained readout (w_pop * s, s >= 0); D2-D1 = amortized D2 minus D1 at n_est_for_D2_D1, by quartile of U")
# ---------------- effect-size views
H("Effect-size views (results/effect_size_summary.csv; from scripts/72_effect_size_analyze.py)")
E = rd("effect_size_summary.csv")
md(E[["dataset", "n_est", "side", "r_all_pop", "r_all_D1", "r_all_D2", "gain_all_D1", "gain_all_D1_se", "r_hi_pop", "r_hi_D1", "gain_hi_D1", "gain_hi_D1_se", "rr_D1", "rr_D2", "pacc_pop", "pacc_D1", "pacc_D2", "pacc_D1_se", "gain_pacc_D1_p"]], 3,
   note="r_all = Pearson r on all held-out items; r_hi = on contested items (top tercile of between-rater disagreement among training raters); rr = residual r (prediction and rating both minus the population item mean); pacc = accuracy on contested pairs (population means within 0.1 SD, rater's ratings differ; tie = 0.5). AADB contested subset and residual r are unreliable (5 ratings per image); EVA seen side is dominated by the 30-rater image mean, use unseen. London here is the dense-matrix reimplementation (results/london65).")
# ---------------- EVA reversal interpretation
H("EVA: what the most-reversed raters reverse (recomputed as in scripts/70_eva_reversal_interpret.py; categories verified by eye: 1 animals, 2 architecture/urban, 3 people, 4 natural landscapes, 5 still life/close-up, 6 other)")
def _eva():
    v = pd.read_csv("data/processed/eva_ratings.csv"); v["image_id"] = v.image_id.astype(str); cat = pd.read_csv("data/raw/eva/image_content_category.csv", dtype=str).rename(columns={"sort": "cat"}); v = v.merge(cat, on="image_id", how="left")
    n = v.groupby("participant_id").size(); v = v[v.participant_id.isin(n[n >= 100].index)]; v["res"] = v.rating - v.groupby("image_id").rating.transform("mean") - v.groupby("participant_id").rating.transform("mean") + v.rating.mean()
    P = v.groupby(["participant_id", "cat"]).res.mean().unstack(); U = rd("sign_check_eva_raters.csv").groupby("rater").U_free.mean().reindex(P.index).dropna(); q4 = U >= U.quantile(0.75)
    rows = [dict(category=c, Q4_mean=P.loc[q4[q4].index, c].mean(), rest_mean=P.loc[q4[~q4].index, c].mean(), mannwhitney_p=mannwhitneyu(P.loc[q4[q4].index, c].dropna(), P.loc[q4[~q4].index, c].dropna()).pvalue) for c in P.columns]
    u = pd.read_csv("data/raw/eva/users.csv", sep="=").set_index("id").reindex(U.index); ok = u.age.notna()
    return dict(rows=rows, n_q4=int(q4.sum()), n_rest=int((~q4).sum()), rho_birth=spearmanr(U[ok], u.age[ok])[0], p_birth=spearmanr(U[ok], u.age[ok])[1], by_gender=str(U.groupby(u.gender_id).mean().round(3).to_dict()), by_level=str(U.groupby(u.photographic_level_id).mean().round(3).to_dict()))
E_ = agg("eva_reversal", _eva)
md(pd.DataFrame(E_["rows"]), 4, note=f"Q4 = most-reversed quartile (n = {E_['n_q4']}) vs rest (n = {E_['n_rest']}); residual rating (0-10 scale) per category")
out.append(f"Spearman(U, birth year) = {E_['rho_birth']:+.3f} (p = {E_['p_birth']:.2g}); mean U by gender (1 = male, 2 = female): {E_['by_gender']}; by photography level (1 beginner, 2 amateur, 3 professional): {E_['by_level']}\n")
# ---------------- dataset screens
H("Dataset screens (variance decomposition; values recorded when the datasets were screened with scripts/22, 27, 50, 56 and 64, not recomputed here)")
out.append("LAPIS residual share 62% (abstract-vs-figurative preference split-half r = 0.96); London 47%; AADB 46% (image mean 46%); EVA 49% (image mean 26%); SCUT 37% (image mean 53%, re-rated residual test-retest 0.12, between-rater residual similarity Asian vs Caucasian r = 0.67); Jester 60% (joke mean 8%); Keller & Vosshall 68% (residual test-retest 0.31). Collaborative-filtering screen (scripts/64_cf_screen.py): London +0.04/+0.06, LAPIS +0.01/+0.03, Jester +0.06/+0.13, AADB/EVA/SCUT/Keller <= +0.01 (insensitive with few raters).\n")
# ---------------- claim revision 2026-10-29: variation-axis structure (79), duplicate-axis diagnostic (80), LAPIS-like synthetic raters (81/82), XPASS-Vis (74-78)
H("Structure of between-rater weight variation (results/var_axis_content.csv; scripts/79): first eigenvector of the per-rater weight covariance in each D2 fold model")
V = rd("var_axis_content.csv"); num = [c for c in V.columns if c not in ("ds", "fold", "seed")]
md(V.groupby("ds")[num].median().reset_index(), 3, note="Medians over fold models. var_share1 = variance share of the first axis; cos_v1_pop = |cos| between the axis and the population weight; pop_proj_over_sd = population projection on the axis / SD of rater projections; frac_opposite = raters on the opposite side of 0 on that axis; bimodality > 0.555 would indicate two modes; cos_neg = raters with negative cosine to the population weight; rho_s_abs = Spearman between the rater's axis score and abstract-minus-figurative preference (LAPIS); r_loading_absr = correlation over the 8 dims between axis loadings and each dim's correlation with abstract preference; rho_s_catN = EVA content categories (1 animals, 2 architecture/urban, 3 people, 4 landscape, 5 still life/close-up, 6 other). The var_axis_{lapis,eva}.pdf captions in figures/INDEX.md give the same quantities pooled over fold models (LAPIS 0.62 SD, 0.27 opposite; EVA 0.63 SD, 0.31 opposite); cos_neg here is the median over fold models (the sign-check table gives the per-rater fraction, LAPIS 0.096).")
H("Can the learned D1 basis reverse a content axis? (results/dup_axis_diag.csv; scripts/80)")
Dd = rd("dup_axis_diag.csv")
md(Dd.groupby(["ds", "content"])[["D1_dup", "D1_pos", "D1_neg", "D1_pop_over_sd", "D1_frac_rev", "D2_pop_over_sd", "D2_frac_rev"]].median().reset_index(), 3, note="Per D1 fold model in the stimulus PCA basis: a_j = w0_j (P_j . u) for the content direction u; D1_pos / D1_neg = summed capacity with the population sign / against it (D1 multipliers = 1); D1_dup = neg/(pos+neg); D1_frac_rev = fraction of held-out raters whose realised D1 readout along u has the opposite sign to the population readout (z at n_est = 100); D2_frac_rev = same for the D2 model. Medians over 20 (LAPIS) fold models.")
if os.path.exists(os.path.join(R, "sim_lapis_like/calibration.csv")):
    H("LAPIS-like synthetic raters on the real LAPIS CLIP features (results/sim_lapis_like/, results/sim_lapis_<cond>_{summary,paired}.csv, results/sign_check_sim_lapis_<cond>_*.csv; scripts/81-82)")
    md(rd("sim_lapis_like/calibration.csv"), 3, note="cont = continuous spread along an axis that is the abstract axis with |cos| 0.59 to the population weight (population projection / SD 0.62); disc = 10% of raters reflect the abstract component (discrete reversal). sigma chosen to match the LAPIS consensus r computed with the same code.")
    def _rows():
        rows = []
        for c in ("cont", "disc"):
            t = rd(f"sim_lapis_like/{c}_truth.csv"); row = dict(cond=c, true_frac_abstract_opposite=(np.sign(t.abs_readout) != np.sign(t.abs_readout.mean())).mean(), true_frac_cos_neg=(t.cos_pop < 0).mean())
            if os.path.exists(os.path.join(R, f"sim_lapis_{c}_paired.csv")):
                P = rd(f"sim_lapis_{c}_paired.csv"); S = rd(f"sim_lapis_{c}_summary.csv")
                for side in ("seen", "unseen"):
                    for con, k in (("D1 - D0", "D1_D0"), ("D2 - D1", "D2_D1")): q = P[(P.n_est == 100) & (P.side == side) & (P.contrast == con)]; row[f"{k}_{side}"] = q.delta.iloc[0] if len(q) else np.nan
                row["r_D0_seen"] = S[(S.kind == "D0") & (S.n_est == 100)].r_amort_seen.iloc[0]; row["r_D2_seen"] = S[(S.kind == "D2") & (S.n_est == 100)].r_amort_seen.iloc[0]
            if os.path.exists(os.path.join(R, f"sign_check_sim_lapis_{c}_raters.csv")):
                r = rd(f"sign_check_sim_lapis_{c}_raters.csv"); rr = r.groupby("rater").mean(numeric_only=True); A = rd(f"sign_check_sim_lapis_{c}_gain.csv"); q = pd.qcut(A.U_free.rank(method="first"), 4, labels=False); qm = A.groupby(q).d2_minus_d1.mean()
                row.update(frac_cos_neg=(rr.cos_pop < 0).mean(), gap_free_minus_D1=rr.gap_free_d1.mean(), frac_gap_gt_0_02=(rr.gap_free_d1 > 0.02).mean(), weight_splithalf_r=rr.halves_r.mean(), D2D1_Q1=qm.get(0, np.nan), D2D1_Q4=qm.get(3, np.nan))
                if os.path.exists(os.path.join(R, f"sim_lapis_like/{c}_truth.csv")):
                    t = rd(f"sim_lapis_like/{c}_truth.csv").set_index("rater").rename(columns={"cos_pop": "true_cos_pop"}); g = rr.join(t, how="inner"); row["spearman_gap_vs_true_abs_readout"] = spearmanr(g.gap_free_d1, g.abs_readout)[0]
                    if c == "disc": row["gap_reflected_minus_rest"] = g[g.reflected].gap_free_d1.mean() - g[~g.reflected].gap_free_d1.mean(); row["D2D1_reflected_minus_rest"] = (A.join(t, how="inner").groupby("reflected").d2_minus_d1.mean().diff().iloc[-1])
            rows.append(row)
        return rows
    rows = agg("sim_lapis_like", _rows)
    md(pd.DataFrame(rows), 3, note="LAPIS targets (same metrics): D2 - D1 +0.021, D1 - D0 +0.12, gap +0.046, frac gap > 0.02 0.53, cos < 0 0.096, D2 - D1 by U quartile +0.009 -> +0.035.")
if os.path.exists(os.path.join(R, "xpass_followup_table.csv")):
    H("XPASS-Vis (same 129 raters: art = LAPIS test images, fashion, scenery; results/xpass_*; scripts/74-78)")
    T = rd("xpass_followup_table.csv"); md(T[T.n_est == 100].drop(columns=["src"]), 3, note="n_est = 100 (the LAPIS-raters-under-XPASS-models row has few raters with >= 110 ratings on the 2,345 images; its n_est = 50 values are D1 - D0 +0.085, D2 - D1 +0.015).")
    md(rd("xpass_cross_q1.csv"), 3, note="Cross-domain Spearman of per-rater measures over the 129 raters (results/xpass_cross_q1.csv).")
    Q2 = rd("xpass_cross_q2.csv"); md(Q2.groupby(["test", "a", "b"]).agg(r=("r", "mean"), p_median=("p", "median"), frac_p05=("p", lambda x: (x < 0.05).mean())).reset_index(), 3, note="Rater-similarity structure shared across domains (Mantel / CCA; results/xpass_cross_q2.csv).")
# ---------------- 2026-11-12: basis dependence of the sign-check metrics (85) and encoder sensitivity (84-87)
if AGG_READ or os.path.exists(os.path.join(R, "basis_dep_lapis_raters.csv")):
    H("Basis dependence of the sign-check metrics (results/basis_dep_<ds>_raters.csv; scripts/85)")
    def _rows():
        rows = []
        for ds in ("london", "scut", "eva", "lapis", "jester"):
            b = rd(f"basis_dep_{ds}_raters.csv").groupby("rater").mean(numeric_only=True); rot = [c for c in b.columns if c.startswith("gap_rot")]; gm = b[rot].mean(); gf = (b[rot] > 0.02).mean()
            rows.append(dict(dataset=ds, n_raters=len(b), gap_model_basis=b.gap_model.mean(), gap_rotated_mean=gm.mean(), gap_rotated_min=gm.min(), gap_rotated_max=gm.max(), gap_pca_basis=b.gap_pca.mean(), gap_scalar=b.gap_scalar.mean(), gap_scalar_se=b.gap_scalar.std() / np.sqrt(len(b)),
                             frac02_model_basis=(b.gap_model > 0.02).mean(), frac02_rotated_mean=gf.mean(), frac02_rotated_min=gf.min(), frac02_rotated_max=gf.max(), frac02_pca_basis=(b.gap_pca > 0.02).mean(), frac02_scalar=(b.gap_scalar > 0.02).mean(),
                             cos_neg_model_basis=(b.cos_model < 0).mean(), cos_neg_orth_rotation=(b.cos_rot < 0).mean(), cos_neg_rawrot_restd=(b.cos_rawrot < 0).mean(), cos_neg_whitened=(b.cos_white < 0).mean(), cos_neg_prediction=(b.cos_pred < 0).mean(), max_abs_dcos_orth_rotation=(rd(f"basis_dep_{ds}_raters.csv").eval("cos_rot - cos_model")).abs().max()))
        return rows
    rows = agg("basis_dependence", _rows)
    md(pd.DataFrame(rows), 4, note="gap = split-half CV r of the free ridge readout minus a constrained readout (per-rater means over fold models; same data, halves and free readout as the sign-check table). model_basis = constraint w_pop * s with one non-negative scale PER DIMENSION in the D2 fold model's standardised 8-dim basis (= gap_free_minus_D1 of the sign-check table); rotated = the same per-dimension constraint after a random orthogonal rotation of that basis (5 rotations: mean, min, max of the dataset means); pca_basis = in the principal axes of the item features; scalar = w = c * w_pop with a single c >= 0 (does not depend on an orthogonal change of basis; a stronger constraint: it removes every deviation from the population direction, not only sign reversals). frac02 = fraction of raters with gap > 0.02. cos_neg = fraction of raters whose weight has a negative cosine with the population weight: model_basis (= frac_cos_neg of the sign-check table), after an orthogonal rotation of the standardised basis (identical; max_abs_dcos is the largest per-row difference), after rotating the raw basis and re-standardising each dimension, in the whitened basis, and as the correlation of the two readouts' predictions over the training items.")
