# ---------------- 2026-11-17: simulated-participant control at the measured reliability (88, 88b) and test statistics of all quoted contrasts (89)
fp = lambda v: "<1e-300" if v < 1e-300 else (f"{v:.2e}" if v < 1e-3 else f"{v:.4f}")
def stat_md(T, note=None):
    T = T.copy()
    for c in ("mean_diff", "sem", "ci95_lo", "ci95_hi"): T[c] = T[c].map(lambda v: f"{v:+.4f}" if c != "sem" else f"{v:.4f}")
    T["t"] = T.t.map(lambda v: f"{v:.2f}"); T["cohen_dz"] = T.cohen_dz.map(lambda v: f"{v:+.3f}"); T["p_t"] = T.p_t.map(fp); T["p_w"] = T.p_w.map(fp)
    out.append(T.to_markdown(index=False)); out.append("")
    if note: out.append(f"_{note}_\n")
if os.path.exists(os.path.join(R, "sim_recovery_matched_summary.csv")):
    H("Simulated-participant control at the measured reliability (results/sim_recovery_matched_summary.csv, sim_recovery_matched_stats.csv; scripts/88, 88b)")
    S = rd("sim_recovery_matched_summary.csv")
    md(S.groupby(["tag", "exp", "sim", "kind"])[["wsd", "noise", "eps", "eps_at_bound", "rho_true_pop", "sim_splithalf", "real_splithalf", "sim_splithalf_fold0", "real_splithalf_fold0", "sim_hold_truepop", "real_hold_pop", "hold_pop", "hold_amortized", "hold_direct", "hold_oracle", "true_pop", "true_amortized"]].mean().reset_index(), 4,
       note="Means over 2 seeds. tag matched = noise SD calibrated so that the est-vs-hold rho of the simulated participants (sim_splithalf; the definition of scripts/48: Spearman between the inverse-MDS RDMs of a random 70 % and the remaining 30 % of the arrangement trials, all participants) equals that of the real participants (real_splithalf), size of the individual differences as before (weight SD 0.6); "
            "tag matched_id = the size of the individual differences (wsd; eps of the D2 type follows) is calibrated as well, so that the held-out rho of the true population RDM (sim_hold_truepop) equals that of the real D0 embedding (real_hold_pop). sim = generating type, kind = fitted model; hold_* = held-out rho on the fold-0 simulated participants (pop = z = 0 of the fitted model); true_* = rho with the noiseless individual RDM. "
            "eps_at_bound = 1: the D2-type family cannot produce individual differences as large as the calibrated D1 type (rho between true and population RDM stays above about 0.37-0.39 even at the upper bound eps = 8), so the matched_id D2-type rows are NOT matched on the population rho (0.35-0.36 instead of 0.30) and are not used. Earlier conditions for comparison: noise 0.30 gave sim_splithalf 0.40 (Exp. 2) and noise 0.45 gave 0.20 (Exp. 1).")
    T = rd("sim_recovery_matched_stats.csv"); stat_md(T[T.unit == "slot, seeds averaged"].drop(columns=["unit"]), note="Paired contrasts of the held-out rho over the fold-0 simulated participants (the two seeds averaged per participant slot; per-seed rows are in the CSV). Columns as in the test-statistics table below.")
