    H("Test statistics for the model comparisons (results/stats_table.csv, results/stats_correlations.csv; scripts/89_stats_table.py)")
    S = rd("stats_table.csv"); lon = rd("london_summary.csv"); lon = lon[lon.n_est == 20].set_index("kind").r_amort; d = S[(S.label == "London Set, 20 faces") & (S.contrast == "D1 - D0")].mean_diff.iloc[0]
    out.append(f"Rounding rule: differences are rounded from the unrounded mean of the per-rater differences, never from the rounded means. London Set, 20 faces: D0 {lon['D0']:.3f}, D1 {lon['D1']:.3f} (table values, 3 decimals), mean difference {d:.4f} -> quote {d:+.3f} (the difference of the rounded means, {lon['D1'] - lon['D0']:+.3f}, is not used).\n")
    stat_md(S.drop(columns=["source_file", "checked_against_paired_csv"]), note=f"Paired contrasts on per-rater values (seeds averaged per rater first). mean_diff, sem (SD / sqrt n), 95 % CI from the t distribution, t and df of the paired t test, cohen_dz = mean / SD of the paired differences, p_t = two-sided paired t, p_w = two-sided Wilcoxon signed-rank; p < 1e-300 underflows to 0 in the CSV. "
            f"{int(S.checked_against_paired_csv.sum())} of {len(S)} rows reproduce the mean difference and n of the existing results/*_paired.csv exactly (asserted in scripts/89); the others have no row there (baseline, free-text, modal-vote and sign-check contrasts) or use more seeds (London image version: 3 seeds here, results/london_img_paired.csv has seeds 0-1 only). Source files are named in the CSV. Sign-check rows are one-sample tests of the per-rater loss against 0.")
    Cc = rd("stats_correlations.csv").drop(columns=["source_file"]); Cc["coef"] = Cc.coef.map(lambda v: f"{v:+.3f}"); Cc["p"] = Cc.p.map(fp); Cc["n_perm"] = Cc.n_perm.map(lambda v: "" if pd.isna(v) else str(int(v))); Cc["n_models"] = Cc.n_models.map(lambda v: "" if pd.isna(v) else str(int(v)))
